using System; using System.IO; using UnityEditor; using UnityEditor.SceneManagement; using UnityEngine; public static class Phase4A_IntegrationFix { public static void Run(){ try { var sc=EditorSceneManager.OpenScene("Assets/Scenes/147VR_MainScene.unity"); var root=GameObject.Find("Prefab_WPBSA_12Foot_Snooker"); if(root==null) throw new Exception("table root missing"); var visual=Find(root.transform,"Visual_Meshes_Drop_Here"); var surface=Find(root.transform,"TABLE SURFACE"); if(visual==null||surface==null) throw new Exception("visual child/surface missing"); root.transform.localScale=new Vector3(.01f,.01f,.01f); visual.localRotation=Quaternion.Euler(0f,90f,0f); surface.localRotation=Quaternion.identity; PrefabUtility.RecordPrefabInstancePropertyModifications(root.transform); PrefabUtility.RecordPrefabInstancePropertyModifications(visual); PrefabUtility.RecordPrefabInstancePropertyModifications(surface); EditorSceneManager.SaveScene(sc); Debug.Log($"[4A FIX] root worldScale={root.transform.lossyScale}; visual rot={visual.eulerAngles}; surface rot={surface.eulerAngles}"); EditorApplication.Exit(0); } catch(Exception e){Debug.LogException(e);EditorApplication.Exit(3);} } static Transform Find(Transform r,string n){foreach(var t in r.GetComponentsInChildren<Transform>(true))if(t.name==n)return t;return null;} }
